/**
 * LegacyAffiliationFixRequest
 *
 * Inputs for the legacy-affiliation backfill.
 *
 * Defaults bias toward safety: ``dry_run=True`` and no re-enrichment.
 * Callers must explicitly opt out of dry-run to mutate the database.
 */
export type LegacyAffiliationFixRequest = {
    /**
     * Dry Run
     *
     * If true, scan and report counters without committing changes. Defaults to true so unprivileged misuse cannot mutate data.
     */
    dry_run?: boolean;
    /**
     * Limit
     *
     * Cap the number of rows scanned. Omit for no cap.
     */
    limit?: number | null;
    /**
     * Org Id
     *
     * Restrict to a single org id. Omit to scan all orgs.
     */
    org_id?: number | null;
    /**
     * Requeue Enrichment
     *
     * If true, mark fixed entities with enrichment_status='pending' so the worker repopulates affiliation from canonical institutions.
     */
    requeue_enrichment?: boolean;
};

/**
 * LegacyAffiliationFixResponse
 *
 * Counter shape returned by the backfill script.
 */
export type LegacyAffiliationFixResponse = {
    /**
     * Fixed
     *
     * Entities whose attributes_json.affiliation was cleared.
     */
    fixed: number;
    /**
     * Matched
     *
     * Entities whose enrichment_source matched the affected providers.
     */
    matched: number;
    /**
     * Mode
     *
     * 'dry-run' or 'applied'
     */
    mode: string;
    /**
     * Requeue Enrichment
     */
    requeue_enrichment: boolean;
    /**
     * Scanned
     *
     * Total entities visited under the filter.
     */
    scanned: number;
};

